import SwiftUI
import UIKit

/// Colors and surfaces from the Paper prototype, variant D ("dark glass").
/// Every token has a light counterpart so the app also reads well in light mode.
enum Theme {
    // Ground
    static let backgroundTop = Color(light: 0xEEF1F7, dark: 0x0B0D12)
    static let backgroundBottom = Color(light: 0xDFE5F1, dark: 0x141826)

    // Text
    static let textPrimary = Color(light: 0x0B0D12, dark: 0xFFFFFF)
    static let textSecondary = Color(light: 0x0B0D12, lightAlpha: 0.66, dark: 0xFFFFFF, darkAlpha: 0.66)
    static let textTertiary = Color(light: 0x0B0D12, lightAlpha: 0.5, dark: 0xFFFFFF, darkAlpha: 0.5)

    // Glass panel (sheets, bubble, pills)
    static let panelFill = Color(light: 0xFFFFFF, lightAlpha: 0.74, dark: 0x1A1C24, darkAlpha: 0.84)
    static let panelBorder = Color(light: 0xFFFFFF, lightAlpha: 0.95, dark: 0xFFFFFF, darkAlpha: 0.18)
    static let panelHighlight = Color(light: 0xFFFFFF, lightAlpha: 0.9, dark: 0xFFFFFF, darkAlpha: 0.08)
    static let panelShadow = Color(light: 0x1A2550, lightAlpha: 0.14, dark: 0x000000, darkAlpha: 0.6)

    // Cards inside the panel
