    static let cardBorder = Color(light: 0x0B0D12, lightAlpha: 0.07, dark: 0xFFFFFF, darkAlpha: 0.08)

    // Controls
    static let controlFill = Color(light: 0x0B0D12, lightAlpha: 0.06, dark: 0xFFFFFF, darkAlpha: 0.08)
