    // Accent
    static let accent = Color(light: 0x2F55F0, dark: 0x3D63FF)
    static let accentSoft = Color(light: 0x3D63FF, dark: 0x9DBBFF)
    static let accentText = Color(light: 0x2341C8, dark: 0xC9D8FF)
    static let accentTint = Color(light: 0x3D63FF, lightAlpha: 0.1, dark: 0x2448F5, darkAlpha: 0.16)
    static let warning = Color(light: 0xA15C00, dark: 0xFCD34D)
    static let warningTint = Color(light: 0xF59E0B, lightAlpha: 0.14, dark: 0xFBBF24, darkAlpha: 0.16)
    static let live = Color(light: 0x16A34A, dark: 0x4ADE80)

    // Orb gradient stops, converted from the prototype's oklab values.
    enum Orb {
        static let core = [Color(hex: 0xFFFFFF), Color(hex: 0xCFF4FF), Color(hex: 0x6FB8FF), Color(hex: 0x306BFF), Color(hex: 0x1A3BD1)]
        static let coreStops: [CGFloat] = [0, 0.16, 0.44, 0.72, 1]
        static let idle = [Color(hex: 0xFFFFFF), Color(hex: 0xEAF7FF), Color(hex: 0xB9D8FF), Color(hex: 0x8FA9EE)]
        static let idleStops: [CGFloat] = [0, 0.22, 0.56, 1]
        static let swirl = [Color(hex: 0x1A3BD1), Color(hex: 0x3E8BFF), Color(hex: 0xBFEFFF), Color(hex: 0x6FB8FF), Color(hex: 0x306BFF), Color(hex: 0x1A3BD1)]
        static let glow = Color(hex: 0x3E8BFF)
        static let ring = Color(hex: 0x9DBBFF)
