}

extension Color {
    init(hex: UInt32, alpha: Double = 1) {
        self.init(
            .sRGB,
            red: Double((hex >> 16) & 0xFF) / 255,
            green: Double((hex >> 8) & 0xFF) / 255,
            blue: Double(hex & 0xFF) / 255,
            opacity: alpha
        )
    }

    init(light: UInt32, lightAlpha: Double = 1, dark: UInt32, darkAlpha: Double = 1) {
        self.init(uiColor: UIColor { traits in
            traits.userInterfaceStyle == .dark
                ? UIColor(Color(hex: dark, alpha: darkAlpha))
                : UIColor(Color(hex: light, alpha: lightAlpha))
        })
    }
}

/// Large, legible type: the app is used by older people at arm's length.
extension Font {
    static let appHeadline = Font.system(size: 26, weight: .semibold)
    static let appTitle = Font.system(size: 22, weight: .semibold)
    static let appBody = Font.system(size: 19, weight: .regular)
    static let appBodyStrong = Font.system(size: 19, weight: .semibold)
    static let appLabel = Font.system(size: 17, weight: .medium)
    static let appCaption = Font.system(size: 15, weight: .semibold)
}

/// Dark translucent surface with a fine light rim and a soft shadow.
struct GlassSurface: ViewModifier {
    var cornerRadius: CGFloat = 28
    var elevated = true

    func body(content: Content) -> some View {
        let shape = RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
        content
            .background {
                shape
                    .fill(.ultraThinMaterial)
                    .overlay(shape.fill(Theme.panelFill))
            }
            .overlay {
                shape.strokeBorder(Theme.panelBorder, lineWidth: 1)
            }
            .overlay(alignment: .top) {
                // Inner top highlight, like light catching the glass edge.
                shape
                    .inset(by: 1)
                    .trim(from: 0, to: 1)
                    .stroke(
                        LinearGradient(colors: [Theme.panelHighlight, .clear], startPoint: .top, endPoint: .center),
                        lineWidth: 1
                    )
            }
            .shadow(color: elevated ? Theme.panelShadow : .clear, radius: 30, y: 18)
    }
}

extension View {
    func glassSurface(cornerRadius: CGFloat = 28, elevated: Bool = true) -> some View {
        modifier(GlassSurface(cornerRadius: cornerRadius, elevated: elevated))
    }
}

/// Large primary and secondary buttons, the same height so neither dominates.
struct BigButtonStyle: ButtonStyle {
    enum Kind { case primary, secondary }
    var kind: Kind

    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(.system(size: 20, weight: .semibold))
            .foregroundStyle(kind == .primary ? Color.white : Theme.textPrimary)
            .frame(maxWidth: .infinity, minHeight: 60)
            .background {
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .fill(kind == .primary ? Theme.accent : Theme.controlFill)
            }
            .overlay {
                if kind == .secondary {
                    RoundedRectangle(cornerRadius: 18, style: .continuous)
                        .strokeBorder(Theme.controlBorder, lineWidth: 1)
                }
            }
            .shadow(color: kind == .primary ? Theme.Orb.shadow.opacity(0.4) : .clear, radius: 12, y: 6)
            .opacity(configuration.isPressed ? 0.75 : 1)
            .scaleEffect(configuration.isPressed ? 0.98 : 1)
            .animation(.easeOut(duration: 0.12), value: configuration.isPressed)
    }
}

struct AppBackground: View {
    var glow: Double = 1

    var body: some View {
        ZStack {
            LinearGradient(colors: [Theme.backgroundTop, Theme.backgroundBottom], startPoint: .top, endPoint: .bottom)
            RadialGradient(
                colors: [Theme.Orb.shadow.opacity(0.22 * glow), .clear],
                center: UnitPoint(x: 0.5, y: 0.86),
                startRadius: 0,
                endRadius: 380
            )
        }
        .ignoresSafeArea()
    }
}

import A2UISwiftUI
import Foundation

// Wire types for the WebSocket `/ws`, see docs/contracts.md § WebSocket.

enum OrbState: String, Codable, CaseIterable {
    case idle, listening, thinking, searching, speaking
}

/// One card from `reply.cards`. The app renders the `a2ui` messages built from these;
/// `raw` keeps the card's JSON so native fallback views can decode it their own way
/// (contracts § Cards: `.convertFromSnakeCase`, `.iso8601`).
struct CardPayload: Decodable, Equatable {
    let kind: String
    let raw: Data

    init(from decoder: Decoder) throws {
        let value = try JSONValue(from: decoder)
        guard case .object(let fields) = value, case .string(let kind)? = fields["kind"] else {
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "card without kind"))
        }
        self.kind = kind
        self.raw = try JSONEncoder().encode(value)
    }
}

struct Reply: Decodable, Equatable {
    let say: String
    let cards: [CardPayload]
}

enum ServerMessage {
    case ready
    case state(OrbState, label: String?)
    case transcript(String)
    case reply(Reply)
    case a2ui([A2uiMessage])
    case audio
    case audioEnd
    case screenOK(summary: String?)
    case error(String)
    case unknown(String)

    /// Decodes one JSON text frame. Unknown `type`s are kept, not thrown, so a newer
    /// server never breaks the app.
    static func decode(_ data: Data) throws -> ServerMessage {
        let envelope = try JSONDecoder().decode(Envelope.self, from: data)
        let decoder = JSONDecoder()
        switch envelope.type {
        case "ready":
            return .ready
        case "state":
            let frame = try decoder.decode(StateFrame.self, from: data)
            return .state(OrbState(rawValue: frame.state) ?? .idle, label: frame.label)
        case "transcript":
            return .transcript(try decoder.decode(TextFrame.self, from: data).text)
        case "reply":
            return .reply(try decoder.decode(Reply.self, from: data))
        case "a2ui":
            // Plain decoder on purpose: A2UI keys are camelCase and data keys must stay untouched.
            return .a2ui(try decoder.decode(A2UIFrame.self, from: data).messages)
        case "audio":
            return .audio
        case "audio_end":
            return .audioEnd
        case "screen_ok":
            return .screenOK(summary: try decoder.decode(ScreenFrame.self, from: data).summary)
        case "error":
            return .error(try decoder.decode(ErrorFrame.self, from: data).message)
        default:
            return .unknown(envelope.type)
        }
    }

    private struct Envelope: Decodable { let type: String }
    private struct StateFrame: Decodable { let state: String; let label: String? }
    private struct TextFrame: Decodable { let text: String }
    private struct A2UIFrame: Decodable { let messages: [A2uiMessage] }
    private struct ScreenFrame: Decodable { let summary: String? }
    private struct ErrorFrame: Decodable { let message: String }
}

enum ClientMessage: Encodable {
    case hello(token: String)
    case text(String)

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: Key.self)
        switch self {
        case .hello(let token):
            try container.encode("hello", forKey: .type)
            try container.encode(token, forKey: .token)
        case .text(let text):
            try container.encode("text", forKey: .type)
            try container.encode(text, forKey: .text)
        }
    }

    private enum Key: String, CodingKey { case type, token, text }
}

/// Minimal JSON tree, used to keep card JSON intact.
enum JSONValue: Codable, Equatable {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() {
            self = .null
        } else if let value = try? container.decode(Bool.self) {
            self = .bool(value)
        } else if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if let value = try? container.decode(String.self) {
            self = .string(value)
        } else if let value = try? container.decode([JSONValue].self) {
            self = .array(value)
        } else {
            self = .object(try container.decode([String: JSONValue].self))
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .null: try container.encodeNil()
        case .bool(let value): try container.encode(value)
        case .number(let value): try container.encode(value)
        case .string(let value): try container.encode(value)
        case .array(let value): try container.encode(value)
        case .object(let value): try container.encode(value)
        }
    }
}

import Foundation

/// Bundled fixtures (see Fixtures/). Fixture mode replays them as the same JSON frames
/// the server sends, so they go through the exact decoding and rendering path.
enum Fixtures {
    struct Turn {
        let label: String
        let frames: [Data]
    }

    /// The demo question: conflict and train cards (`demo_reply.json`, `demo_a2ui.json`).
    static var demo: Turn {
        Turn(
            label: "Checking trains…",
            frames: [
                frame(type: "reply", merging: object("demo_reply")),
                frame(type: "a2ui", merging: ["messages": array("demo_a2ui")]),
            ]
        )
    }

    /// The other two kinds: event and flight (`cards.json`, `cards_a2ui.json`).
    static var otherKinds: Turn {
        Turn(
            label: "Checking your calendar…",
            frames: [
                frame(type: "reply", merging: [
                    "say": "Next weekend is the hackathon, and on Tuesday you fly to Lisbon.",
                    "cards": array("cards"),
                ]),
                frame(type: "a2ui", merging: ["messages": array("cards_a2ui")]),
            ]
        )
    }

    /// Picks the fixture turn for a typed question.
    static func turn(for question: String) -> Turn {
        let q = question.lowercased()
        let other = ["flight", "fly", "event", "week", "calendar", "on today"]
        return other.contains(where: q.contains) ? otherKinds : demo
    }

    static var screenOK: Data {
        frame(type: "screen_ok", merging: ["summary": object("screen")["summary"] ?? NSNull()])
    }

    // MARK: - Loading

    static func data(_ name: String) -> Data {
        guard let url = Bundle.main.url(forResource: name, withExtension: "json"),
              let data = try? Data(contentsOf: url) else {
            preconditionFailure("missing fixture \(name).json")
        }
        return data
    }

    private static func object(_ name: String) -> [String: Any] {
        (try? JSONSerialization.jsonObject(with: data(name))) as? [String: Any] ?? [:]
    }

    private static func array(_ name: String) -> [Any] {
        (try? JSONSerialization.jsonObject(with: data(name))) as? [Any] ?? []
    }

    private static func frame(type: String, merging fields: [String: Any]) -> Data {
        var object = fields
        object["type"] = type
        return (try? JSONSerialization.data(withJSONObject: object)) ?? Data()
    }
}

import Foundation

/// `URLSessionWebSocketTask` client for `/ws` (contracts § WebSocket): sends `hello`,
/// hands every decoded frame to `onMessage`, and reconnects 1 s after any drop.
@MainActor
final class WebSocketClient {
    enum Status: Equatable {
        case disconnected
        case connecting
        case connected
        case failed(String)
    }

    var onMessage: (ServerMessage) -> Void = { _ in }
    var onStatus: (Status) -> Void = { _ in }

    private let session = URLSession(configuration: .default)
    private var task: URLSessionWebSocketTask?
    private var endpoint: (url: URL, token: String)?
    private var generation = 0
    private var reconnect: Task<Void, Never>?

    private(set) var status: Status = .disconnected {
        didSet { if status != oldValue { onStatus(status) } }
    }

    /// Turns what people paste into settings ("https://x.trycloudflare.com",
    /// "x.trycloudflare.com", "ws://192.168.1.5:8000/ws") into the `/ws` URL.
    static func endpointURL(from text: String) -> URL? {
        var raw = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !raw.isEmpty else { return nil }
        if !raw.contains("://") { raw = "https://" + raw }
        guard var parts = URLComponents(string: raw), let host = parts.host, !host.isEmpty else { return nil }
        switch parts.scheme?.lowercased() {
        case "https", "wss": parts.scheme = "wss"
        case "http", "ws": parts.scheme = "ws"
        default: return nil
        }
        if parts.path.isEmpty || parts.path == "/" { parts.path = "/ws" }
        return parts.url
    }

    func connect(url: URL, token: String) {
        endpoint = (url, token)
        open()
    }

    /// Reconnects now if the socket is not up, e.g. when the app comes back to the foreground.
    func ensureConnected() {
        guard endpoint != nil, status != .connected, status != .connecting else { return }
        open()
    }

    func disconnect() {
        endpoint = nil
        reconnect?.cancel()
        generation += 1
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
        status = .disconnected
    }

    func send(_ message: ClientMessage) {
        guard let task, let data = try? JSONEncoder().encode(message),
              let text = String(data: data, encoding: .utf8) else { return }
        task.send(.string(text)) { [weak self] error in
            guard let error else { return }
            Task { @MainActor in self?.dropped(error.localizedDescription) }
        }
    }

    // MARK: - Private

    private func open() {
        guard let endpoint else { return }
        reconnect?.cancel()
        generation += 1
        let current = generation
        task?.cancel(with: .goingAway, reason: nil)

        let task = session.webSocketTask(with: endpoint.url)
        self.task = task
        status = .connecting
        task.resume()
        send(.hello(token: endpoint.token))
        Task { await receive(on: task, generation: current) }
    }

    private func receive(on task: URLSessionWebSocketTask, generation current: Int) async {
        while current == generation {
            do {
                let frame = try await task.receive()
                guard current == generation else { return }
                let data: Data
                switch frame {
                case .string(let text): data = Data(text.utf8)
                case .data(let bytes): data = bytes
                @unknown default: continue
                }
                do {
                    let message = try ServerMessage.decode(data)
                    if case .ready = message { status = .connected }
                    onMessage(message)
                } catch {
                    print("ws: undecodable frame: \(error)")
                }
            } catch {
                guard current == generation else { return }
                let reason = task.closeReason.flatMap { String(data: $0, encoding: .utf8) }
                dropped(reason.flatMap { $0.isEmpty ? nil : $0 } ?? error.localizedDescription)
                return
            }
        }
    }

    private func dropped(_ reason: String) {
        guard endpoint != nil else { return }
        generation += 1
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
        status = .failed(reason)
        reconnect?.cancel()
        reconnect = Task { [weak self] in
            try? await Task.sleep(for: .seconds(1))
            guard !Task.isCancelled else { return }
            self?.open()
        }
    }
}

import A2UISwiftCore
import A2UISwiftUI
import Foundation
import Observation

/// Everything the one screen shows, driven by server frames (or fixture frames).
/// Only the latest turn is kept: there is no chat thread.
@MainActor
@Observable
final class AgentSession {
    enum Connection: Equatable {
        case fixtures
        case connecting
        case live
        case offline(String)
    }

    struct ScreenNotice: Equatable {
        let id = UUID()
        let summary: String?
    }

    /// How long the screen chip stays up (WP1 task 8).
    static let screenChipLifetime: Duration = .seconds(120)

    private(set) var orb: OrbState = .idle
    private(set) var label: String?
    private(set) var transcript: String?
    private(set) var reply: Reply?
    /// Tool steps of the current turn, e.g. "Checking trains…", shown as a one-line trail.
    private(set) var steps: [String] = []
    private(set) var surfaces: [SurfaceViewModel] = []
    private(set) var screen: ScreenNotice?
    private(set) var errorMessage: String?
    private(set) var connection: Connection = .fixtures

    private let client = WebSocketClient()
    private var fixtureTurn: Task<Void, Never>?
    private var screenExpiry: Task<Void, Never>?

    init() {
        client.onMessage = { [weak self] in self?.handle($0) }
        client.onStatus = { [weak self] status in
            guard let self, connection != .fixtures else { return }
            switch status {
            case .disconnected: connection = .offline("Not connected")
            case .connecting: if connection != .live { connection = .connecting }
            case .connected: connection = .live
            case .failed(let reason): connection = .offline(reason)
            }
        }
    }

    // MARK: - Connection

    /// Applies the settings: fixture mode, or the live server at `serverURL`.
    func configure(useFixtures: Bool, serverURL: String, token: String) {
        guard !useFixtures, let url = WebSocketClient.endpointURL(from: serverURL) else {
            client.disconnect()
            connection = .fixtures
            return
        }
        connection = .connecting
        client.connect(url: url, token: token)
    }

    func appBecameActive() {
        client.ensureConnected()
    }

    // MARK: - Asking

    /// A typed question (debug field or intent chip): `text` on the wire.
    func ask(_ question: String) {
        let question = question.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !question.isEmpty else { return }
        transcript = question
        if connection == .fixtures {
            runFixtureTurn(question)
        } else {
            client.send(.text(question))
        }
    }

    /// Fixture mode only: what the server sends after the iPhone Shortcut posts a screenshot.
    func simulateScreenshot() {
        receive(Fixtures.screenOK)
    }

    // MARK: - Server frames

    func handle(_ message: ServerMessage) {
        switch message {
        case .ready, .audio, .audioEnd, .unknown:
            break  // Audio is WP1 tasks 6-7.
        case .state(let state, let label):
            if state == .thinking && orb != .thinking && orb != .searching {
                steps = []  // a new turn starts
                errorMessage = nil
            }
            if state == .searching, let label, steps.last != label {
                steps.append(label)
            }
            orb = state
            self.label = label
        case .transcript(let text):
            transcript = text
        case .reply(let reply):
            self.reply = reply
            surfaces = []
            errorMessage = nil
        case .a2ui(let messages):
            surfaces = Self.surfaces(from: messages)
        case .screenOK(let summary):
            showScreen(ScreenNotice(summary: summary))
        case .error(let message):
            errorMessage = message
        }
    }

    /// Decodes one fixture frame through the same path as a live frame.
    func receive(_ frame: Data) {
        do {
            handle(try ServerMessage.decode(frame))
        } catch {
            print("fixture frame failed to decode: \(error)")
        }
    }

    /// One `SurfaceViewModel(catalog: basicCatalog)` per surface (contracts § A2UI).
    static func surfaces(from messages: [A2uiMessage]) -> [SurfaceViewModel] {
        var order: [String] = []
        var models: [String: SurfaceViewModel] = [:]
        for message in messages {
            let id = message.surfaceId
            if models[id] == nil {
                models[id] = SurfaceViewModel(catalog: basicCatalog)
                order.append(id)
            }
            let errors = models[id]?.processMessages([message]) ?? []
            for error in errors { print("a2ui \(id): \(error)") }
        }
        return order.compactMap { models[$0] }.filter { $0.componentTree != nil }
    }

    // MARK: - Private

    private func showScreen(_ notice: ScreenNotice) {
        screen = notice
        screenExpiry?.cancel()
        screenExpiry = Task { [weak self] in
            try? await Task.sleep(for: Self.screenChipLifetime)
            guard !Task.isCancelled, self?.screen?.id == notice.id else { return }
            self?.screen = nil
        }
    }

    /// Replays a fixture reply with the server's timing: thinking, a tool step, the
    /// reply and cards, then speaking until roughly when the spoken answer would end.
    private func runFixtureTurn(_ question: String) {
        fixtureTurn?.cancel()
        let turn = Fixtures.turn(for: question)
        fixtureTurn = Task { [weak self] in
            func step(_ state: OrbState, _ label: String? = nil, wait: Double) async -> Bool {
                self?.handle(.state(state, label: label))
                try? await Task.sleep(for: .seconds(wait))
                return !Task.isCancelled
            }
            guard await step(.thinking, wait: 0.9) else { return }
            guard await step(.searching, turn.label, wait: 1.1) else { return }
            turn.frames.forEach { self?.receive($0) }
            let words = Double(self?.reply?.say.split(separator: " ").count ?? 10)
            guard await step(.speaking, wait: max(2, words * 0.32)) else { return }
            self?.handle(.state(.idle, label: nil))
        }
    }
}

extension A2uiMessage {
    var surfaceId: String {
        switch self {
        case .createSurface(let payload): payload.surfaceId
        case .updateComponents(let payload): payload.surfaceId
        case .updateDataModel(let payload): payload.surfaceId
        case .deleteSurface(let payload): payload.surfaceId
        }
    }
}

import SwiftUI

/// The assistant's presence: one orb, a look per state (Paper "11 Orb states").
/// Sizes are the prototype's, scaled by `scale` (1 = 104 pt orb).
struct OrbView: View {
    let state: OrbState
    var scale: CGFloat = 1.2

    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    private var orbSize: CGFloat { 104 * scale }
    private var slot: CGFloat { 214 * scale }

    var body: some View {
        TimelineView(.animation(paused: reduceMotion)) { timeline in
            let t = reduceMotion ? 0 : timeline.date.timeIntervalSinceReferenceDate
            ZStack {
                rings(t)
                orb(t)
            }
            .frame(width: slot, height: slot)
        }
        .accessibilityElement()
        .accessibilityLabel(Text(OrbView.title(for: state)))
    }

    // MARK: - Orb body

    @ViewBuilder
    private func orb(_ t: Double) -> some View {
        switch state {
        case .idle:
            let breathe = 1 + 0.025 * sin(t * 2 * .pi / 4)
            Circle()
                .fill(RadialGradient(
                    stops: zip(Theme.Orb.idle, Theme.Orb.idleStops).map { .init(color: $0, location: $1) },
                    center: UnitPoint(x: 0.34, y: 0.28), startRadius: 0, endRadius: orbSize * 0.82
                ))
                .overlay(innerShade(opacity: 0.18))
                .frame(width: orbSize * 0.78, height: orbSize * 0.78)
                .shadow(color: Theme.Orb.shadow.opacity(0.18), radius: 14 * scale, y: 10 * scale)
                .opacity(0.94)
                .scaleEffect(breathe)
        case .thinking, .searching:
            let speed = state == .searching ? 1.6 : 0.9
            Circle()
                .fill(AngularGradient(colors: Theme.Orb.swirl, center: .center, angle: .degrees(210 + t * 90 * speed)))
                .overlay(
                    Circle().fill(RadialGradient(
                        colors: [.white.opacity(0.95), .white.opacity(0)],
                        center: UnitPoint(x: 0.34, y: 0.28), startRadius: 0, endRadius: orbSize * 0.42
                    ))
                )
                .overlay(innerShade(opacity: 0.3))
                .frame(width: orbSize, height: orbSize)
                .shadow(color: Theme.Orb.shadow.opacity(0.35), radius: 20 * scale, y: 14 * scale)
        case .listening, .speaking:
            let pulse = state == .listening ? 1 + 0.03 * sin(t * 2 * .pi / 1.2) : 1
            coreOrb
                .frame(width: orbSize, height: orbSize)
                .scaleEffect(pulse)
        }
    }

    private var coreOrb: some View {
        Circle()
            .fill(RadialGradient(
                stops: zip(Theme.Orb.core, Theme.Orb.coreStops).map { .init(color: $0, location: $1) },
                center: UnitPoint(x: 0.34, y: 0.28), startRadius: 0, endRadius: orbSize * 0.82
            ))
            .overlay(innerShade(opacity: 0.35))
            .shadow(color: Theme.Orb.shadow.opacity(0.45), radius: 20 * scale, y: 14 * scale)
    }

    /// Darkens the bottom edge so the orb reads as a sphere.
    private func innerShade(opacity: Double) -> some View {
        Circle()
            .fill(LinearGradient(
                colors: [.clear, Color(hex: 0x0A145A, alpha: opacity)],
                startPoint: UnitPoint(x: 0.5, y: 0.55), endPoint: .bottom
            ))
    }

    // MARK: - Rings

    @ViewBuilder
    private func rings(_ t: Double) -> some View {
        switch state {
        case .idle:
            EmptyView()
        case .listening:
            let swell = 0.5 + 0.5 * sin(t * 2 * .pi / 1.2)
            ZStack {
                Circle()
                    .fill(RadialGradient(colors: [Theme.Orb.glow.opacity(0.18), .clear], center: .center, startRadius: 0, endRadius: 80 * scale))
                    .frame(width: 160 * scale, height: 160 * scale)
                Circle()
                    .strokeBorder(Theme.Orb.ring.opacity(0.3 + 0.15 * swell), lineWidth: 1.5)
                    .frame(width: 160 * scale, height: 160 * scale)
                    .scaleEffect(1 + 0.03 * swell)
                Circle()
                    .strokeBorder(Theme.Orb.ring.opacity(0.14 + 0.1 * swell), lineWidth: 1)
                    .frame(width: 210 * scale, height: 210 * scale)
                    .scaleEffect(1 + 0.02 * swell)
            }
        case .thinking, .searching:
            let speed = state == .searching ? 1.0 : 0.6
            ZStack {
                Circle()
                    .strokeBorder(Theme.Orb.ring.opacity(0.12), lineWidth: 2)
                    .frame(width: 150 * scale, height: 150 * scale)
                Circle()
                    .trim(from: 0, to: 0.22)
                    .stroke(Theme.Orb.ring, style: StrokeStyle(lineWidth: 2.5, lineCap: .round))
                    .frame(width: 148 * scale, height: 148 * scale)
                    .rotationEffect(.degrees(t * 360 * speed))
                if state == .searching {
                    Circle()
                        .trim(from: 0, to: 0.12)
                        .stroke(Theme.Orb.ring.opacity(0.55), style: StrokeStyle(lineWidth: 2, lineCap: .round))
                        .frame(width: 186 * scale, height: 186 * scale)
                        .rotationEffect(.degrees(-t * 240))
                }
            }
        case .speaking:
            let ripple = (t / 1.6).truncatingRemainder(dividingBy: 1)
            ZStack {
                Circle()
                    .fill(RadialGradient(colors: [Theme.Orb.glow.opacity(0.28), .clear], center: .center, startRadius: 0, endRadius: 80 * scale))
                    .frame(width: 160 * scale, height: 160 * scale)
                Circle()
                    .strokeBorder(Theme.Orb.ring.opacity(0.45), lineWidth: 3)
                    .frame(width: 160 * scale, height: 160 * scale)
                Circle()
                    .strokeBorder(Theme.Orb.ring.opacity(0.1), lineWidth: 1)
                    .frame(width: 210 * scale, height: 210 * scale)
                Circle()
                    .strokeBorder(Theme.Orb.ring.opacity(0.4 * (1 - ripple)), lineWidth: 2)
                    .frame(width: 160 * scale, height: 160 * scale)
                    .scaleEffect(1 + 0.32 * ripple)
            }
        }
    }

    static func title(for state: OrbState) -> String {
        switch state {
        case .idle: "Ready"
        case .listening: "Listening"
        case .thinking: "Working on it"
        case .searching: "Searching"
        case .speaking: "Speaking"
        }
    }
}

/// The glass pill under the orb: what the assistant is doing, or the tool status label.
struct OrbLabel: View {
    let state: OrbState
