import A2UISwiftCore
import A2UISwiftUI
import SwiftUI

/// The reply's cards. A2UI surfaces are the main path (contracts § A2UI); when a reply
/// has cards but no `a2ui` frame, `nativeCards` is the switch point for native views.
struct CardsView: View {
    let surfaces: [SurfaceViewModel]
    let cards: [CardPayload]

    var body: some View {
        if !surfaces.isEmpty {
            VStack(spacing: 14) {
                ForEach(surfaces.indices, id: \.self) { i in
                    A2UISurfaceView(viewModel: surfaces[i], scrolls: false)
                }
            }
            .a2uiCatalogItem(.card) { context in
                guard let child = context.node.children.first else { return nil }
                return AnyView(GlassCard { context.buildChild(child) })
            }
            .a2uiCatalogItem(.column) { context in
                // Card bodies stack their lines tightly; the root column spaces the cards.
                let isCardBody = context.node.id.hasSuffix("-body")
                return AnyView(
                    VStack(alignment: .leading, spacing: isCardBody ? 2 : 14) {
                        ForEach(context.node.children, id: \.id) { context.buildChild($0) }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                )
            }
        } else if !cards.isEmpty {
            nativeCards(cards)
        }
    }

    /// Fallback for replies without `a2ui` (WP1 task 3). Native card views from
    /// `frontend/BeaverAgent/NativeCards/` plug in here, e.g.
    /// `ForEach(cards) { NativeCardView(card: $0, onAction: ...) }`.
    @ViewBuilder
    private func nativeCards(_ cards: [CardPayload]) -> some View {
        EmptyView()
    }
}

/// The A2UI `Card`, drawn as a glass card from the prototype's result panel.
private struct GlassCard<Content: View>: View {
    @ViewBuilder var content: Content

    var body: some View {
        let shape = RoundedRectangle(cornerRadius: 22, style: .continuous)
        content
            .padding(.horizontal, 12)
            .padding(.vertical, 12)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(shape.fill(Theme.cardFill))
            .overlay(shape.strokeBorder(Theme.cardBorder, lineWidth: 1))
    }
}

extension SurfaceViewModel {
    /// Large type for the card text variants the server uses (h2, body, caption).
    func applyAppStyle() {
        var style = a2uiStyle
        style.primaryColor = Theme.accent
        style.leafMargin = 4
        style.textStyles = [
            "h1": .init(font: .system(size: 34, weight: .bold), color: Theme.textPrimary),
            "h2": .init(font: .system(size: 30, weight: .semibold), color: Theme.textPrimary),
            "h3": .init(font: .system(size: 24, weight: .semibold), color: Theme.textPrimary),
            "h4": .init(font: .system(size: 22, weight: .semibold), color: Theme.textPrimary),
            "h5": .init(font: .system(size: 20, weight: .semibold), color: Theme.textPrimary),
            "body": .init(font: .system(size: 19, weight: .medium), color: Theme.textPrimary.opacity(0.92)),
            "caption": .init(font: .system(size: 17, weight: .regular), color: Theme.textSecondary),
        ]
        a2uiStyle = style
    }
}

