import SwiftUI

/// The one screen: screen chip, the latest turn (question, mascot line, cards), and the orb.
struct ContentView: View {
    @Bindable var session: AgentSession
    @Binding var sheet: AppSheet?

    var body: some View {
        ZStack(alignment: .bottom) {
            AppBackground(glow: session.orb == .idle ? 0.6 : 1)

            ScrollView {
                VStack(alignment: .leading, spacing: 18) {
                    if let screen = session.screen {
                        ScreenChip(summary: screen.summary)
                            .transition(.move(edge: .top).combined(with: .opacity))
                    }
                    turn
                }
                .padding(.horizontal, 20)
                .padding(.top, 8)
                .padding(.bottom, 330)
                .animation(.spring(duration: 0.4), value: session.screen)
                .animation(.spring(duration: 0.4), value: session.reply)
            }
            .scrollIndicators(.hidden)
            .safeAreaInset(edge: .top) { topBar }

            orbDock
        }
    }

    // MARK: - Top bar

    private var topBar: some View {
        HStack(spacing: 12) {
            Text("Micro Intent")
                .font(.system(size: 20, weight: .bold))
                .foregroundStyle(Theme.textPrimary)
            Spacer()
            ConnectionBadge(connection: session.connection)
            Button {
                sheet = .settings
            } label: {
                Image(systemName: "gearshape")
                    .font(.system(size: 20, weight: .medium))
                    .foregroundStyle(Theme.textPrimary)
                    .frame(width: 48, height: 48)
                    .glassSurface(cornerRadius: 24, elevated: false)
            }
            .accessibilityLabel("Settings")
        }
        .padding(.horizontal, 20)
        .padding(.vertical, 8)
    }

    // MARK: - Latest turn

    @ViewBuilder
    private var turn: some View {
        if let transcript = session.transcript {
            Text("“\(transcript)”")
                .font(.system(size: 22, weight: .medium))
                .foregroundStyle(Theme.textSecondary)
                .fixedSize(horizontal: false, vertical: true)
                .padding(.horizontal, 4)
        }
        if let reply = session.reply {
            MascotBubble(say: reply.say, steps: session.steps)
                .id(reply.say)
                .transition(.opacity.combined(with: .scale(scale: 0.97, anchor: .top)))
            CardsView(surfaces: session.surfaces, cards: reply.cards)
                .transition(.opacity.combined(with: .move(edge: .bottom)))
        } else if session.transcript == nil {
            Welcome()
        }
        if let error = session.errorMessage {
            Label(error, systemImage: "exclamationmark.triangle.fill")
                .font(.appBodyStrong)
                .foregroundStyle(Theme.warning)
                .padding(16)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill(Theme.warningTint))
        }
    }

    // MARK: - Orb dock

    private var orbDock: some View {
        VStack(spacing: 4) {
            if session.reply != nil && session.orb == .idle {
                IntentChips { session.ask($0) }
                    .transition(.opacity)
            }
            OrbView(state: session.orb, scale: 1.05)
                .contentShape(Circle())
                .onLongPressGesture(minimumDuration: 0.5) {
                    sheet = .debug
                }
                .accessibilityAddTraits(.isButton)
                .accessibilityHint("Touch and hold to type a question")
                .accessibilityAction(named: "Type a question") { sheet = .debug }
            OrbLabel(state: session.orb, label: orbLabel)
        }
        .padding(.bottom, 12)
        .frame(maxWidth: .infinity)
        .background(alignment: .bottom) {
            // Fades the scrolling cards out behind the orb.
            LinearGradient(colors: [Theme.backgroundBottom.opacity(0), Theme.backgroundBottom], startPoint: .top, endPoint: .center)
                .frame(height: 330)
                .ignoresSafeArea()
                .allowsHitTesting(false)
        }
        .animation(.easeInOut(duration: 0.3), value: session.orb)
    }

    private var orbLabel: String? {
        if session.orb == .idle { return "Hold to ask" }
        return session.label
    }
}

enum AppSheet: String, Identifiable {
    case settings, debug
    var id: String { rawValue }
}

// MARK: - Pieces

private struct Welcome: View {
    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text("What do you need?")
                .font(.system(size: 36, weight: .bold))
                .tracking(-0.5)
                .foregroundStyle(Theme.textPrimary)
            Text("Look at something on your phone, then hold the orb and ask.")
                .font(.appBody)
                .foregroundStyle(Theme.textSecondary)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(.top, 28)
        .padding(.horizontal, 4)
    }
}

/// What the mascot says (`reply.say`), plus the turn's tool steps as one quiet line.
struct MascotBubble: View {
    let say: String
    let steps: [String]

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            if !steps.isEmpty {
                Label(steps.map(Self.pastTense).joined(separator: " · "), systemImage: "checkmark.circle.fill")
                    .font(.appCaption)
                    .foregroundStyle(Theme.accentText)
                    .lineLimit(1)
            }
            Text(say)
                .font(.appHeadline)
                .tracking(-0.3)
                .foregroundStyle(Theme.textPrimary)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(20)
        .frame(maxWidth: .infinity, alignment: .leading)
        .glassSurface(cornerRadius: 26)
        .overlay(alignment: .bottomLeading) {
            BubbleTail()
                .fill(Theme.panelFill)
                .frame(width: 22, height: 12)
                .offset(x: 30, y: 11)
                .accessibilityHidden(true)
        }
        .accessibilityElement(children: .combine)
    }

    /// "Checking trains…" → "Checked trains".
    static func pastTense(_ label: String) -> String {
        var text = label.trimmingCharacters(in: CharacterSet(charactersIn: "…. "))
        if let first = text.split(separator: " ").first, first.hasSuffix("ing") {
            let stem = first.dropLast(3)
            let past = stem.hasSuffix("e") ? stem + "d" : stem + "ed"
            text = String(past) + text.dropFirst(first.count)
        }
        return text
    }
}

private struct BubbleTail: Shape {
    func path(in rect: CGRect) -> Path {
        var path = Path()
        path.move(to: CGPoint(x: rect.minX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY))
        path.addQuadCurve(to: CGPoint(x: rect.minX + 4, y: rect.maxY), control: CGPoint(x: rect.minX + 8, y: rect.minY + 4))
        path.closeSubpath()
        return path
    }
}

/// Shown on `screen_ok`: what the server read from the latest screenshot.
struct ScreenChip: View {
    let summary: String?

    var body: some View {
        HStack(alignment: .top, spacing: 12) {
            Image(systemName: summary == nil ? "eye.slash" : "eye")
                .font(.system(size: 17, weight: .semibold))
                .foregroundStyle(summary == nil ? Theme.warning : Theme.accentSoft)
                .frame(width: 34, height: 34)
                .background(Circle().fill(summary == nil ? Theme.warningTint : Theme.accentTint))
            VStack(alignment: .leading, spacing: 2) {
                Text(summary == nil ? "Couldn't read that screen" : "I see")
                    .font(.appCaption)
                    .foregroundStyle(summary == nil ? Theme.warning : Theme.accentText)
                if let summary {
                    Text(summary)
                        .font(.appLabel)
                        .foregroundStyle(Theme.textPrimary)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            Spacer(minLength: 0)
        }
        .padding(14)
        .glassSurface(cornerRadius: 22)
        .accessibilityElement(children: .combine)
    }
}

/// Two or three follow-up questions after an answer; each sends a typed turn.
private struct IntentChips: View {
    let ask: (String) -> Void
    private let intents: [(String, String)] = [
        ("calendar", "Am I free?"),
        ("tram", "How do I get there?"),
        ("airplane", "When is my flight?"),
    ]

    var body: some View {
        ScrollView(.horizontal) {
            HStack(spacing: 8) {
                ForEach(intents, id: \.1) { icon, text in
                    Button { ask(text) } label: {
                        Label(text, systemImage: icon)
                            .font(.system(size: 16, weight: .medium))
                            .foregroundStyle(Theme.textPrimary.opacity(0.9))
                            .padding(.horizontal, 14)
                            .frame(minHeight: 44)
                            .glassSurface(cornerRadius: 22, elevated: false)
                    }
                }
            }
            .padding(.horizontal, 20)
        }
        .scrollIndicators(.hidden)
    }
}

struct ConnectionBadge: View {
    let connection: AgentSession.Connection

    var body: some View {
        HStack(spacing: 8) {
            Circle()
                .fill(color)
                .frame(width: 9, height: 9)
            Text(text)
                .font(.system(size: 15, weight: .semibold))
                .foregroundStyle(Theme.textSecondary)
                .lineLimit(1)
        }
        .padding(.horizontal, 14)
        .frame(height: 36)
        .glassSurface(cornerRadius: 18, elevated: false)
        .accessibilityElement(children: .combine)
    }

    private var text: String {
        switch connection {
        case .fixtures: "Demo data"
        case .connecting: "Connecting…"
        case .live: "Live"
        case .offline: "Offline"
        }
    }

    private var color: Color {
        switch connection {
        case .fixtures: Theme.accentSoft
        case .connecting: Theme.warning
        case .live: Theme.live
        case .offline: Color(hex: 0xF87171)
        }
    }
}

import SwiftUI

enum SettingsKey {
    static let serverURL = "serverURL"
    static let token = "token"
    static let useFixtures = "useFixtures"
    static let appearance = "appearance"
}

enum Appearance: String, CaseIterable, Identifiable {
    case system, light, dark
    var id: String { rawValue }
    var title: String { rawValue.capitalized }
    var colorScheme: ColorScheme? {
        switch self {
        case .system: nil
        case .light: .light
        case .dark: .dark
        }
    }
}

/// Server URL and token live here and nowhere else (contracts § Environment).
struct SettingsSheet: View {
    @AppStorage(SettingsKey.serverURL) private var serverURL = ""
    @AppStorage(SettingsKey.token) private var token = ""
    @AppStorage(SettingsKey.useFixtures) private var useFixtures = true
    @AppStorage(SettingsKey.appearance) private var appearance = Appearance.system

    let connection: AgentSession.Connection
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        SheetScaffold(title: "Settings") {
            VStack(alignment: .leading, spacing: 22) {
                Toggle(isOn: $useFixtures) {
                    VStack(alignment: .leading, spacing: 2) {
                        Text("Use demo data")
                            .font(.appBodyStrong)
                            .foregroundStyle(Theme.textPrimary)
                        Text("Replays saved answers, no server needed")
                            .font(.system(size: 16))
                            .foregroundStyle(Theme.textSecondary)
                    }
                }
                .tint(Theme.accent)
                .padding(16)
                .background(fieldBackground)

                VStack(alignment: .leading, spacing: 14) {
                    LabeledField(title: "Server URL") {
                        TextField("https://….trycloudflare.com", text: $serverURL)
                            .keyboardType(.URL)
                            .textContentType(.URL)
                            .textInputAutocapitalization(.never)
                            .autocorrectionDisabled()
                    }
                    LabeledField(title: "Token") {
                        SecureField("App token", text: $token)
                            .textInputAutocapitalization(.never)
                            .autocorrectionDisabled()
                    }
                    if !useFixtures {
                        HStack(spacing: 10) {
                            ConnectionBadge(connection: connection)
                            if case .offline(let reason) = connection {
                                Text(reason)
                                    .font(.system(size: 15))
                                    .foregroundStyle(Theme.textSecondary)
                                    .lineLimit(2)
                            }
                        }
                    }
                }
                .disabled(useFixtures)
                .opacity(useFixtures ? 0.45 : 1)

                VStack(alignment: .leading, spacing: 8) {
                    Text("Appearance")
                        .font(.appCaption)
                        .foregroundStyle(Theme.textSecondary)
                    Picker("Appearance", selection: $appearance) {
                        ForEach(Appearance.allCases) { Text($0.title).tag($0) }
                    }
                    .pickerStyle(.segmented)
                    .controlSize(.large)
                }
            }
        } actions: {
            Button("Done") { dismiss() }
                .buttonStyle(BigButtonStyle(kind: .primary))
        }
    }

    private var fieldBackground: some View {
        RoundedRectangle(cornerRadius: 18, style: .continuous).fill(Theme.controlFill)
    }
}

/// Long-press on the orb: type a question instead of speaking it (`text` on the wire).
struct DebugSheet: View {
    let isFixtureMode: Bool
    let ask: (String) -> Void
    let simulateScreenshot: () -> Void

    @State private var question = ""
    @FocusState private var focused: Bool
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        SheetScaffold(title: "Type a question") {
            VStack(alignment: .leading, spacing: 16) {
                TextField("Can I make it?", text: $question, axis: .vertical)
                    .font(.system(size: 22, weight: .medium))
                    .foregroundStyle(Theme.textPrimary)
                    .lineLimit(1...4)
                    .focused($focused)
                    .submitLabel(.send)
                    .onSubmit(send)
                    .padding(18)
                    .background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill(Theme.controlFill))
                    .overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).strokeBorder(Theme.controlBorder))
                if isFixtureMode {
                    Button {
                        simulateScreenshot()
                        dismiss()
                    } label: {
                        Label("Pretend a screenshot arrived", systemImage: "camera.viewfinder")
                            .font(.appLabel)
                            .foregroundStyle(Theme.accentText)
                            .frame(minHeight: 44)
                    }
                }
            }
        } actions: {
            HStack(spacing: 12) {
                Button("Cancel") { dismiss() }
                    .buttonStyle(BigButtonStyle(kind: .secondary))
                Button("Ask", action: send)
                    .buttonStyle(BigButtonStyle(kind: .primary))
                    .disabled(question.trimmingCharacters(in: .whitespaces).isEmpty)
            }
        }
        .onAppear { focused = true }
    }

    private func send() {
        ask(question)
        dismiss()
    }
}

// MARK: - Building blocks

/// Glass sheet with a large title, content, and big buttons at the bottom.
private struct SheetScaffold<Content: View, Actions: View>: View {
    let title: String
    @ViewBuilder var content: Content
    @ViewBuilder var actions: Actions

    var body: some View {
        VStack(alignment: .leading, spacing: 24) {
            Text(title)
                .font(.system(size: 28, weight: .bold))
                .foregroundStyle(Theme.textPrimary)
                .padding(.top, 28)
            ScrollView {
                content
            }
            .scrollBounceBehavior(.basedOnSize)
            actions
        }
        .padding(.horizontal, 22)
        .padding(.bottom, 12)
        .presentationBackground {
            ZStack {
                Rectangle().fill(.ultraThinMaterial)
                Theme.panelFill
            }
        }
        .presentationCornerRadius(32)
        .presentationDragIndicator(.visible)
    }
}

private struct LabeledField<Field: View>: View {
    let title: String
    @ViewBuilder var field: Field

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title)
                .font(.appCaption)
                .foregroundStyle(Theme.textSecondary)
            field
                .font(.system(size: 19))
                .foregroundStyle(Theme.textPrimary)
                .padding(.horizontal, 16)
                .frame(minHeight: 56)
                .background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(Theme.controlFill))
                .overlay(RoundedRectangle(cornerRadius: 16, style: .continuous).strokeBorder(Theme.controlBorder))
        }
    }
}

import SwiftUI

@main
struct BeaverAgentApp: App {
    @State private var session = AgentSession()
    @State private var sheet: AppSheet?
    @AppStorage(SettingsKey.serverURL) private var serverURL = ""
    @AppStorage(SettingsKey.token) private var token = ""
    @AppStorage(SettingsKey.useFixtures) private var useFixtures = true
    @AppStorage(SettingsKey.appearance) private var appearance = Appearance.system
    @Environment(\.scenePhase) private var scenePhase

    var body: some Scene {
        WindowGroup {
            ContentView(session: session, sheet: $sheet)
                .sheet(item: $sheet) { sheet in
                    switch sheet {
                    case .settings:
                        SettingsSheet(connection: session.connection)
                    case .debug:
                        DebugSheet(
                            isFixtureMode: session.connection == .fixtures,
                            ask: session.ask,
                            simulateScreenshot: session.simulateScreenshot
                        )
                        .presentationDetents([.medium, .large])
                    }
                }
                .preferredColorScheme(appearance.colorScheme)
                .task {
                    applySettings()
                    DemoLaunch.apply(to: session, sheet: $sheet)
                }
                .onChange(of: settingsKey) { applySettings() }
                .onChange(of: scenePhase) { _, phase in
                    if phase == .active { session.appBecameActive() }
                }
        }
    }

    private var settingsKey: String { "\(useFixtures)|\(serverURL)|\(token)" }

    private func applySettings() {
        session.configure(useFixtures: useFixtures, serverURL: serverURL, token: token)
    }
}

/// Launch arguments for rehearsals and screenshots, e.g.
/// `-demoScene searching`, `-demoSheet debug`, `-demoAsk "Can I make it?"`.
@MainActor
enum DemoLaunch {
    static func apply(to session: AgentSession, sheet: Binding<AppSheet?>) {
        let defaults = UserDefaults.standard
        if let scene = defaults.string(forKey: "demoScene") {
            play(scene, on: session)
        }
        if let name = defaults.string(forKey: "demoSheet"), let value = AppSheet(rawValue: name) {
            sheet.wrappedValue = value
        }
        if let question = defaults.string(forKey: "demoAsk") {
            Task {
                try? await Task.sleep(for: .seconds(2))
                session.ask(question)
            }
        }
    }

    private static func play(_ scene: String, on session: AgentSession) {
        let question = "Can I make it to dinner in Bern?"
        switch scene {
        case "listening":
            session.handle(.state(.listening, label: nil))
        case "thinking":
            session.handle(.transcript(question))
            session.handle(.state(.thinking, label: nil))
        case "searching":
            session.handle(.transcript(question))
            session.handle(.state(.thinking, label: nil))
            session.handle(.state(.searching, label: "Checking trains…"))
        case "speaking", "reply", "kinds":
            let turn = scene == "kinds" ? Fixtures.otherKinds : Fixtures.demo
            session.handle(.transcript(scene == "kinds" ? "What's coming up this week?" : question))
            session.handle(.state(.thinking, label: nil))
            session.handle(.state(.searching, label: turn.label))
            turn.frames.forEach(session.receive)
            session.handle(.state(scene == "speaking" ? .speaking : .idle, label: nil))
        case "screen":
            session.simulateScreenshot()
        case "error":
            session.handle(.transcript(question))
            session.handle(.error("Sorry, something went wrong."))
        default:
            break
        }
    }
}

